+const SEMANTIC_AMENDMENT_KEYS = new Set([
+	"kind",
+	"version",
+	"id",
+	"bindingId",
+	"executionRunId",
+	"predecessorRevisionId",
+	"authorizationId",
+	"humanStep",
+	"approvalStep",
+	"parentLineageId",
+	"beforeCommit",
+	"afterCommit",
+	"beforeBlobHash",
+	"afterBlobHash",
+	"approvedPlanCommit",
