+			resumeCompatible: false,
+			completionAuthorized: false,
+			currentRevisionId: null,
+			history: [],
+			diagnostic: folded.diagnostic,
+			minimumToolchain: AMENDED_RUN_MINIMUM_TOOLCHAIN,
+		};
+	}
